import { useEffect, useState } from "react";
import axios from "axios";
import "./Catalogo.css";

export default function Catalogo(){

 const [esmeraldas,setEsmeraldas] = useState([]);

 useEffect(()=>{

  cargarEsmeraldas();

 },[]);


 const cargarEsmeraldas = async ()=>{

  try{

   const res = await axios.get("http://localhost:3000/api/esmeraldas");

   setEsmeraldas(res.data);

  }catch(error){

   console.log("Error cargando esmeraldas");

  }

 };


 return(

  <div className="catalogo-container">

   <h1 className="titulo">
    Catálogo de Esmeraldas
   </h1>

   <div className="grid">

    {esmeraldas.map((e)=>(
     
     <div key={e.id_esmeralda} className="card">

      <div className="icono">💎</div>

      <h2>{e.nombre}</h2>

      <p className="descripcion">
       {e.descripcion}
      </p>

      <hr/>

      <div className="info">

       <div>

        <span className="tipo">
         {e.tipo}
        </span>

        <p>Cert: {e.certificado}</p>

       </div>

       <div className="precio">

        <span>Precio</span>

        <h3>${e.precio}</h3>

       </div>

      </div>

      <button className="btn-detalles">
       VER DETALLES
      </button>

     </div>

    ))}

   </div>

  </div>

 );

}
